bounds_c.content:
#include "bounds.h"
int theta_bounds_hold(long long n) {
    const long long cube = n * n * n;
    const long long t = cube - 3 * n * n - n + 1;
    const int lower_ok = cube <= 2 * t;
    const int upper_ok = t <= 2 * cube;
    return n >= 7 && t >= 0 && lower_ok && upper_ok;
}
